const putRiskType = `-- name: PutRiskType :exec
INSERT INTO authz_risk_types (realm_id, name, enabled, band_medium, band_high, created_at, updated_at) VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (realm_id, name) DO UPDATE SET enabled = excluded.enabled, band_medium = excluded.band_medium, band_high = excluded.band_high,
    updated_at = excluded.updated_at
`

type PutRiskTypeParams struct {
	RealmID    string
	Name       string
	Enabled    int64
	BandMedium int64
	BandHigh   int64
	CreatedAt  string
	UpdatedAt  string
}

func (q *Queries) PutRiskType(ctx context.Context, arg PutRiskTypeParams) error {
	_, err := q.db.ExecContext(ctx, putRiskType,
		arg.RealmID,
		arg.Name,
		arg.Enabled,
		arg.BandMedium,
		arg.BandHigh,
		arg.CreatedAt,
		arg.UpdatedAt,
	)
	return err
}

